-- =========================================================================
-- D24 — les 206 textes intégraux ouverts d'Anarchief.org, en EPUB, sur leur
-- notice ; la liste « Autres formats » de la notice montre aussi les EPUB
-- =========================================================================
-- Date     : 2026-10-23
-- Chantier : documents numériques — EPUB des textes intégraux d'Anarchief.org
-- Auteur   : Claude (assistant·e), pour la coordination
-- Ref      : backlog D24 ; 20261023130916_d25_word_et_odt_admis_en_telechargement
--            (api.book_documents_v1) ; 20261023152846_d24_le_seau_epub_restreint_…
--            Convertisseur hors dépôt (E:\CCLA\BLMF\AnarBib\Relações\Anarchief.org\
--            convertisseur : epub-anarchief.py, droits-anarchief.py)
--
-- POURQUOI
--   Décision de Xavier du 23/10/2026 (questionnaire D24) : les textes intégraux
--   transcrits sur le wiki d'Anarchief se publient en EPUB, les 208 ouverts
--   (lettre A ou A + B de J/M dans la feuille des lots de textes, rendue le
--   19/10) d'abord ; sur une notice qui a déjà un PDF principal, l'EPUB se
--   montre dans la liste de la notice, rebaptisée « Autres formats ».
--
-- CE QUI EST FAIT HORS DE CE PAQUET (23/10/2026)
--   206 EPUB 3 fabriqués par pandoc depuis le wikitexte (métadonnées Dublin
--   Core : titre, auteur, langue, date, source, mention de droits du lot) ; les
--   pages 322 et 1164 n'ont pas de notice (322 : Theorie en praktijk, fusion en
--   attente de J/M, G21). Versés dans anarbib-epub-public, sous
--   books/<notice>/anarchief-<page>.epub, depuis la session (aal2) de
--   l'administration du réseau, empreinte SHA-256 de chaque fichier comparée
--   au manifeste avant l'envoi : 206 objets, 7 148 311 octets.
--
-- CE QUE FAIT LE PAQUET
--   1. api.book_documents_v1 liste aussi les EPUB (« Autres formats »), sauf
--      la ressource principale, que le bouton « Lire » montre déjà. Droits et
--      règles de visibilité inchangés (CREATE OR REPLACE : ACL gardée).
--   2. 206 ressources « epub » (lecture en ligne, publiques, licenca_livre,
--      validées : fichier et notice de la même source, NUMDIF-6), principales
--      là où la notice n'en a pas (150 : le lien vers le wiki y était seul et
--      non principal), et la justification du lot de textes. Rejouable : une
--      ressource déjà posée au même chemin n'est pas recréée.
--
-- CHECKLIST DOCTRINE
--   [x] Donnée gardée : 206 en production (chaque objet présent), 0 au banc
--   [x] Porte : ACL vérifiée inchangée (anon, authenticated ; pas PUBLIC)
--   [x] Aucun verrou de table (INSERT de lignes, une fonction remplacée)
-- =========================================================================

BEGIN;

-- 1. « Autres formats » : documents et EPUB qui ne sont pas la ressource principale
CREATE OR REPLACE FUNCTION api.book_documents_v1(p_book_id bigint)
RETURNS TABLE(asset_id bigint, label text, mime_type text, access_scope text, access_granted boolean, file_size_bytes bigint)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $fn$
  SELECT r.id, r.label, r.mime_type, r.access_scope,
         CASE WHEN r.access_scope = 'publico' THEN true
              ELSE public.fn_current_user_conta_ativa() AND public.fn_current_user_is_member_of_holding_library(r.book_id) END,
         CASE WHEN r.metadata->>'file_size_bytes' ~ '^\d{1,15}$' THEN (r.metadata->>'file_size_bytes')::bigint END
    FROM public.book_digital_resources r
   WHERE r.book_id = p_book_id
     AND r.resource_type IN ('documento', 'epub')
     AND NOT coalesce(r.is_primary, false)
     AND r.status = 'active' AND coalesce(r.is_active, false)
     AND r.storage_path IS NOT NULL
     AND ((r.access_scope = 'publico' AND coalesce(r.bibliographic_match_validated, false))
          OR r.access_scope = 'conta_ativa')
     AND EXISTS (SELECT 1 FROM public.book_holdings h
                  WHERE h.book_id = r.book_id AND private.fn_catalog_library_visible_to_caller(h.library_id))
   ORDER BY r.resource_type, r.label, r.id
$fn$;
COMMENT ON FUNCTION api.book_documents_v1(bigint) IS
  'D25 puis D24 (23/10/2026) : les « autres formats » d''une notice — fichiers Word/ODT à télécharger, EPUB à lire — hors la ressource principale. Porte publique (anon) : catalogue lisible, public validé, restreint signalé avec access_granted. Lecture par read-digital-asset.';

DO $garde_porte$
BEGIN
  IF has_function_privilege('anon', 'api.book_documents_v1(bigint)', 'EXECUTE') IS NOT TRUE
     OR NOT has_function_privilege('authenticated', 'api.book_documents_v1(bigint)', 'EXECUTE')
     OR (SELECT proacl::text FROM pg_proc WHERE oid = 'api.book_documents_v1(bigint)'::regprocedure) ~ '(^|[{,])=X/' THEN
    RAISE EXCEPTION 'D24 : les droits de api.book_documents_v1 ont changé';
  END IF;
END
$garde_porte$;

-- 2. les 206 ressources EPUB
DO $d24$
DECLARE
  c_anarchief constant uuid := '1bb157fd-4d1f-415b-9e5d-490f4f8d0895';
  c_seau      constant text := 'anarbib-epub-public';
  v_n int; v_principales int; v_manque text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.libraries WHERE id = c_anarchief) THEN
    RAISE NOTICE 'D24 : bibliothèque Anarchief.org absente (banc), rien à faire.';
    RETURN;
  END IF;

  CREATE TEMP TABLE d24_epub (book_id bigint, page int, chemin text, sha256 text, taille bigint, page_url text, justif text) ON COMMIT DROP;

  SELECT string_agg(e.page::text, ',') INTO v_manque FROM d24_epub e
   WHERE NOT private.fn_objet_stocke_existe(c_seau, e.chemin)
      OR NOT EXISTS (SELECT 1 FROM public.book_holdings h WHERE h.book_id = e.book_id AND h.library_id = c_anarchief)
      OR NOT EXISTS (SELECT 1 FROM public.books b WHERE b.id = e.book_id AND b.bib_ref = 'ANARCHIEF-' || e.page);
  IF v_manque IS NOT NULL THEN
    RAISE EXCEPTION 'D24 : objet absent, notice non détenue ou cote différente pour les pages %', v_manque;
  END IF;

    book_id, resource_type, usage_type, access_scope, status, is_active, is_primary, mime_type,
    label, notes, metadata, source_url, source_page_url, source_name, attribution_text,
    rights_status, rights_justification, bibliographic_match_validated,
    storage_bucket, storage_path, language_code, activated_at)
  SELECT e.book_id, 'epub', 'leitura_online', 'publico', 'active', true,
         NOT EXISTS (SELECT 1 FROM public.book_digital_resources p
                      WHERE p.book_id = e.book_id AND p.is_primary AND p.is_active AND p.status = 'active'),
         'application/epub+zip',
         left(b.titulo || ' (texto integral, EPUB)', 300),
         'Texto integral transcrito no wiki da fonte (Anarchief.org, página ' || e.page || '), convertido em EPUB pela AnarBib em 23/10/2026. '
           || 'Arquivo e ficha da mesma fonte (NUMDIF-6) ; validado pela administração da rede (D24).',
         jsonb_build_object('sha256', e.sha256, 'file_size_bytes', e.taille, 'source_identifier', 'anarchief:' || e.page,
                            'source_file', 'anarchief-' || e.page || '.epub', 'deposited_via', 'D24 : versement depuis la session de l''administration du réseau',
                            'conversion', 'pandoc mediawiki -> epub3 (epub-anarchief.py)'),
         e.page_url, e.page_url, 'Anarchief.org',
         'Fonte: Anarchief.org (página ' || e.page || ')',
         'licenca_livre', e.justif, true,
         c_seau, e.chemin,
         CASE WHEN b.idioma ~ '^[a-z]{2,3}(-[A-Z]{2})?$' THEN b.idioma END,
         now()
    FROM d24_epub e JOIN public.books b ON b.id = e.book_id
   WHERE NOT EXISTS (SELECT 1 FROM public.book_digital_resources x WHERE x.storage_bucket = c_seau AND x.storage_path = e.chemin);

  SELECT count(*), count(*) FILTER (WHERE r.is_primary) INTO v_n, v_principales
    FROM public.book_digital_resources r JOIN d24_epub e ON r.storage_bucket = c_seau AND r.storage_path = e.chemin
   WHERE r.resource_type = 'epub' AND r.is_active;
  IF v_n <> 206 THEN
    RAISE EXCEPTION 'D24 : % ressources EPUB, 206 attendues', v_n;
  END IF;
  RAISE NOTICE 'D24 : 206 ressources EPUB ouvertes, dont % principales.', v_principales;
END
$d24$;

COMMIT;
